#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzSample_envTex(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_envTex(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_dropletCount;
uniform float amzp_expandSpeed;
uniform float amzp_heightFactor;
uniform float amzp_rippleFreq;
uniform float amzp_timeSpeed;
uniform float amzp_seed;
uniform float amzp_normalOffset;
uniform float amzp_normalStrength;
uniform float amzp_blend;
uniform float amzp_alpha;
uniform float amzp_dropletsOnly;
uniform float amzp_shockwave;
uniform float amzp_shockStrength;
uniform float amzp_shockWidth;



    const float PI = 3.141592653589793;


    float hash11(float p) {
      p = fract(p * 0.1031);
      p *= p + 33.33;
      p *= p + p;
      return fract(p);
    }
    float hash21(float2 p) {
      float3 p3 = fract(float3(p.xyx) * 0.1031);
      p3 += dot(p3, p3.yzx + 33.33);
      return fract((p3.x + p3.y) * p3.z);
    }
    float2 hash22(float2 p) {
      float n = hash21(p);
      float m = hash21(p + 17.17);
      return float2(n, m);
    }


    float getDropletHeight(float2 uv) {
      float timeVal = (time + amzp_seed) * amzp_timeSpeed;
      float height = 0.0;

      int N = int(clamp(float(amzp_dropletCount), 1.0, 64.0));
      for (int i = 0; i < 64; ++i) {
        if (i >= N) break;
        float fi = float(i);


        float decayRate = 0.323 + 2.0 * hash11(fi * 1.123 + 0.237);
        float dropletStrength = hash11(fi * 0.713 + 0.001);
        float dropletStrengthBias = 0.1 + 0.2 * hash11(fi * 2.371 + 0.345);

        float dropFractionFull = timeVal / decayRate;
        float dropIndex = floor(dropFractionFull);
        float dropFraction = fract(dropFractionFull);


        float2 rnd = hash22(float2(fi * 0.731 + dropIndex * 0.1, dropIndex * 1.123));
        float2 dropletPosition = rnd * 2.0 - 1.0; 

        float ringRadius = amzp_expandSpeed * dropFraction * dropletStrength - dropletStrengthBias;
        ringRadius = max(ringRadius, 0.0001);

        float distToDroplet = distance(uv, dropletPosition);
        float within = distToDroplet > ringRadius ? 0.0 : 1.0;

        float edgeDist = max(0.0, ringRadius - distToDroplet) / ringRadius;
        float h = within > 0.5 ? distToDroplet : 0.0;

        h = cos(PI + (h - ringRadius) * amzp_rippleFreq * dropletStrength) * 0.5 + 0.5;
        h *= 1.0 - dropFraction; 
        h *= within > 0.5 ? distToDroplet / ringRadius : 0.0;


        float shaped = (1.0 - (cos(h * PI) + 1.0) * 0.5);
        height += shaped * amzp_heightFactor;
      }
      return height;
    }


    float3 getDropletNormal(float2 uv) {
      float off = amzp_normalOffset;
      float3 ofs = float3(-off, 0.0, off);

      float s11 = getDropletHeight(uv);
      float s01 = getDropletHeight(uv + ofs.xy);
      float s21 = getDropletHeight(uv + ofs.zy);
      float s10 = getDropletHeight(uv + ofs.yx);
      float s12 = getDropletHeight(uv + ofs.yz);

      float3 va = normalize(float3(ofs.z, 0.0, s21 - s11));
      float3 vb = normalize(float3(0.0, ofs.z, s12 - s11));

      float3 n = normalize(cross(va, vb));
      n.xy *= s11 * amzp_normalStrength;
      return normalize(n);
    }

    void amzRender(){

      float2 aspect = float2(screen.zw.x / screen.zw.y, 1.0);
      float2 uv = (amzScreenNorm() - 0.5) * 2.0;
      uv.x *= aspect.x;


      float3 normal = getDropletNormal(uv);


      float h = getDropletHeight(uv);
      float mask = clamp(h * 8.0, 0.0, 1.0);



      float2 envUV = normal.xy * 0.5 + 0.5;
      float3 envColor = amzTexture(1, envUV).rgb;


      float2 srcUV = amzScreenNorm();
      if((amzp_shockwave>0.5) && !(amzp_dropletsOnly>0.5)){
        float eps = max(0.001, amzp_normalOffset);
        float hx = getDropletHeight(uv + float2(eps, 0.0)) - getDropletHeight(uv - float2(eps, 0.0));
        float hy = getDropletHeight(uv + float2(0.0, eps)) - getDropletHeight(uv - float2(0.0, eps));
        float2 grad = float2(hx, hy) / (2.0 * eps);
        float edge = clamp(length(grad) * amzp_shockWidth, 0.0, 1.0);
        float2 dir = normalize(grad + 1e-6);
        float2 offset = dir * edge * amzp_shockStrength;

        float2 offsetScreen = float2(offset.x / aspect.x, offset.y) * 0.5;

        srcUV += offsetScreen * mask;
      }

      float4 src = amzTexture(0, srcUV);


      if((amzp_dropletsOnly>0.5)){

        float3 col = envColor * mask;
        float a = mask * amzp_alpha;
        amzOutput = float4(col, 1.0) * a;
      } else {

        float3 outRGB = mix(src.rgb, src.rgb + envColor * mask, clamp(amzp_blend, 0.0, 1.0));
        float a = src.a * amzp_alpha;
        amzOutput = float4(outRGB, 1.0) * a;
      }
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

